const raw = wb.getRange("'Raw Data'!A1:F18").getValues();
const out = [];
for (let c = 0; c < 6; c++) for (let r = 0; r < raw.length; r++) { const v = raw[r][c]; if (typeof v === 'number' && Number.isInteger(v)) out.push(v); }
const grid = [];
for (let i = 0; i < out.length; i += 6) { const row = out.slice(i, i + 6); while (row.length < 6) row.push(null); grid.push(row); }
const sh = wb.getWorksheet('Numbers');
grid.forEach((row, r) => row.forEach((v, c) => { if (v !== null) sh.getRange({rowStart:r,colStart:c,rowEnd:r,colEnd:c}).setValue(v); }));
log('count', out.length, 'rows', grid.length);
const got = wb.getRange("Numbers!A1:F9").getValues();
const man = wb.getRange("'Manual Result'!A1:F9").getValues();
const diffs = [];
for (let r=0;r<9;r++) for (let c=0;c<6;c++) if ((got[r][c]??null)!==(man[r][c]??null)) diffs.push([r,c,got[r][c],man[r][c]]);
log('diffs vs manual', JSON.stringify(diffs));
log(wb.getWorksheet('Numbers').getUsedRange?.());
wb.getRange("Numbers!A1:F9")

